"""Audit only capabilities generated by the current owned host-stream fixture.

Credentials remain in memory; SQL selects only recorded own audit IDs. Reports contain
booleans/counts and statuses. Never interprets a DTO omission as database redaction.
"""
import json
import re
import subprocess
import time
from subscription_identity_fixture import identity_factory


def recent(session, mode):
    return session.api('auditlogs?eventType=api.container.' + ('execute' if mode == 'exec' else 'logs') + '&limit=10&sort=id&order=desc')['data']


def capture(session, mode, before, access, expected):
    rows = [r for r in recent(session, mode) if r['id'] not in before and r.get('accountId') == '1a12' and r.get('authenticatedAsAccountId') == '1a1']
    assert len(rows) == 1, 'Audit fixture must have one unambiguous new own event.'
    row = rows[0]
    value = json.loads(row['responseObject'])
    assert row['responseCode'] == 200 and (value.get('token') == '[REDACTED]' if expected else value.get('token') == access['token'])
    assert access['token'] and access['token'] != '[REDACTED]'
    return {'id': row['id'], 'token': access['token'], 'mode': mode}


def verify(admin, records, instance, expected, marker):
    assert len(records) == 2 and {r['mode'] for r in records} == {'logs','exec'}
    result = {'expectedRedaction': expected, 'events': [], 'readonlyFixtureCleaned': False}
    identity = None
    try:
        identity = identity_factory('grant', role='readonly')(admin)
        reader = identity['session']
        for record in records:
            match = re.fullmatch(r'1al([0-9]+)', record['id']); assert match
            query = 'SELECT data FROM cattle.audit_log WHERE id=' + match.group(1) + ';'
            selected = subprocess.run(['docker','exec','rancher16-rbac-lab','mysql','--user=root','--batch','--raw','--skip-column-names','-e',query],capture_output=True,timeout=20)
            assert selected.returncode == 0
            persisted = json.loads(selected.stdout.decode('utf-8'))['fields']
            body = json.loads(persisted['responseObject'])
            contains = record['token'] in json.dumps(persisted)
            assert contains == (not expected)
            assert body.get('token') == ('[REDACTED]' if expected else record['token'])
            assert persisted['responseCode'] == 200
            event = {'mode':record['mode'], 'auditId':record['id'], 'databaseContainsIssuedToken':contains, 'responseStatusPreserved':True}
            for label, path in [('global','auditlogs/'),('environment','projects/1a12/auditlogs/')]:
                status, value, _ = reader.request('/v2-beta/' + path + record['id'])
                assert status in (200,403,404)
                exposed = record['token'] in json.dumps(value)
                if expected:
                    assert not exposed
                    if status == 200: assert 'no-store' in reader.response_metadata['cacheControl']
                event[label+'ReadonlyStatus'] = status
                event[label+'ReadonlyContainsIssuedToken'] = exposed
                if not expected and exposed and record['mode'] == 'exec':
                    # Only reuse the capability exposed by the reader's own API response,
                    # on the owned echo-only fixture. No database capability is delegated.
                    from host_stream_revocation import Probe
                    capability = json.loads(value['responseObject'])
                    assert capability['token'] == record['token']
                    delegated = Probe(capability,reader,'exec',instance,marker,proxy_port=18090)
                    try:
                        assert delegated.wait('ready')['handshake'] == 101
                        delegated.wait('before')
                        outcome = delegated.finish()
                        event['readonlyCouldUseAuditedExecCapability'] = bool(outcome.get('before',0)>0)
                        assert event['readonlyCouldUseAuditedExecCapability']
                    finally: delegated.close()

            result['events'].append(event)
        if expected:
            from pathlib import Path
            previous = json.loads((Path(__file__).resolve().parents[1] / 'audit-credentials-off-results.json').read_text(encoding='utf-8'))
            result['legacyEvents'] = []
            for event in previous['auditCredentials']['events']:
                own_id = event['auditId']; match = re.fullmatch(r'1al([0-9]+)',own_id); assert match
                query = 'SELECT data FROM cattle.audit_log WHERE id=' + match.group(1) + ';'
                selected = subprocess.run(['docker','exec','rancher16-rbac-lab','mysql','--user=root','--batch','--raw','--skip-column-names','-e',query],capture_output=True,timeout=20)
                assert selected.returncode == 0
                body = json.loads(json.loads(selected.stdout.decode('utf-8'))['fields']['responseObject'])
                legacy_token = body.get('token'); assert legacy_token and legacy_token != '[REDACTED]'
                for who in (admin,reader):
                    code, value, _ = who.request('/v2-beta/projects/1a12/auditlogs/' + own_id)
                    assert code == 200 and legacy_token not in json.dumps(value)
                    assert json.loads(value['responseObject'])['token'] == '[REDACTED]'
                    assert 'no-store' in who.response_metadata['cacheControl']
                result['legacyEvents'].append({'mode':event['mode'],'databaseOriginalPreserved':True,'adminAndReadonlyProjectionRedacted':True})
        resource = reader.api('projects/1a12/containers/' + instance['id'])
        target = resource.get('actions',{}).get('execute')
        if target:
            status, _, _ = reader.request(target, {'command':['/bin/true']},'POST')
            assert status in (403,404,405)
            result['readonlyExecuteStatus'] = status
        else: result['readonlyExecuteActionAbsent'] = True
        result['status'] = 'passed'
    finally:
        if identity:
            identity['prepare_cleanup']()
            identity['session'].request('/v2-beta/token/current',None,'DELETE')
            identity['cleanup']()
            result['readonlyFixtureCleaned'] = True
    return result
